<template>
  <AccountLayout bare><main class="cc-page">
    <header class="cc-header"><div><p class="cc-kicker">PROFILES / ACCOUNT HOLDERS</p><h1>{{ form.id ? 'Edit Credit Card' : 'Create New Credit Card' }}</h1><p>Add and manage your company's credit cards</p></div><button class="btn btn-outline-primary" @click="resetForm">← Back to Credit Cards</button></header>
    <div v-if="error" class="alert alert-danger">{{ error }}</div>
    <section class="cc-stats"><article><span>▣</span><small>Total Cards</small><b>{{ cards.length }}</b></article><article><span>▣</span><small>Total Credit Limit</small><b>{{ money(totalLimit) }}</b></article><article><span>▣</span><small>Current Balance</small><b>{{ money(totalBalance) }}</b></article><article><span>✓</span><small>Active Cards</small><b>{{ activeCards }}</b></article></section>
    <div class="cc-layout">
      <aside class="cc-list card"><div class="cc-list-head"><h2>All Credit Cards ({{ cards.length }})</h2><button class="btn btn-primary btn-sm" @click="newCard">＋ Add New Card</button></div><div class="cc-search"><input v-model="search" class="form-control" placeholder="Search card number or company" /></div><button v-for="card in filteredCards" :key="card.id" class="cc-card" :class="{selected: form.id===card.id}" @click="edit(card)"><span class="cc-brand" :class="card.card_type.toLowerCase().replaceAll(' ','-')">{{ brandLabel(card) }}</span><span class="cc-card-data"><b>{{ card.card_nickname }}</b><small>{{ card.masked_card_number }}</small><em>Limit {{ money(card.credit_limit) }} · Balance {{ money(card.current_balance) }}</em></span><span class="badge" :class="card.status_active?'text-bg-success':'text-bg-secondary'">{{ card.status_active?'Active':'Inactive' }}</span></button><p v-if="!filteredCards.length" class="text-muted text-center py-4 mb-0">No credit cards found.</p></aside>
      <form class="cc-form" @submit.prevent="save">
        <section class="card cc-section"><h2>▣ Card Information</h2><div class="cc-grid four"><Field label="Card Nickname" required><input v-model="form.card_nickname" class="form-control" required placeholder="e.g., Main Company Card" /></Field><Field label="Card Number" :required="!form.id"><input v-model="form.card_number" class="form-control" :required="!form.id" inputmode="numeric" :placeholder="form.id ? 'Leave blank to keep current number' : '1234 5678 9012 3456'" /></Field><Field label="Type" required><select v-model="form.card_type" class="form-select"><option v-for="type in cardTypes" :key="type">{{ type }}</option></select></Field><Field label="Card Network" required><select v-model="form.card_network" class="form-select"><option v-for="network in networks" :key="network">{{ network }}</option></select></Field><Field label="Cardholder Name" required><input v-model="form.cardholder_name" class="form-control" required placeholder="Name as shown on card" /></Field><Field label="Expiry Date" required><input v-model="form.expiry_date" class="form-control" required placeholder="MM/YY" maxlength="5" /></Field><Field label="CVV" :required="!form.id"><input v-model="form.cvv" type="password" inputmode="numeric" maxlength="4" class="form-control" :required="!form.id" placeholder="123" /></Field><Field label="Credit Limit" required><input v-model.number="form.credit_limit" type="number" min="0" step=".01" class="form-control" required /></Field><Field label="Current Balance"><input v-model.number="form.current_balance" type="number" min="0" step=".01" class="form-control" /></Field></div><div class="cc-grid five cc-schedule"><Field label="Billing Date" required><DaySelect v-model="form.billing_day" /></Field><Field label="Due Date" required><DaySelect v-model="form.due_day" /></Field><Field label="Pay Date" required><DaySelect v-model="form.pay_day" /></Field><Field label="Status" required><select v-model="form.status_active" class="form-select"><option :value="true">Active</option><option :value="false">Inactive</option></select></Field><Field label="Available Credit"><div class="cc-readonly">{{ money(availableCredit) }}</div></Field></div></section>
        <section class="card cc-section"><h2>▣ Billing Information</h2><div class="cc-grid four"><Field label="Billing Address"><input v-model="form.billing_address" class="form-control" /></Field><Field label="City"><input v-model="form.city" class="form-control" /></Field><Field label="State / Province"><input v-model="form.state" class="form-control" /></Field><Field label="Postal / ZIP Code"><input v-model="form.postal_code" class="form-control" /></Field><Field label="Country"><select v-model="form.country_id" class="form-select"><option :value="null">Select Country</option><option v-for="country in options.countries" :key="country.id" :value="country.id">{{ country.country_name }}</option></select></Field><Field label="Phone Number"><input v-model="form.phone_number" class="form-control" /></Field><Field label="Email"><input v-model="form.email" type="email" class="form-control" /></Field></div></section>
        <section class="card cc-section"><h2>▣ Account Information</h2><div class="cc-grid four"><Field label="Account"><select v-model="form.account_holder_id" class="form-select"><option :value="null">Select Account</option><option v-for="account in options.accounts" :key="account.id" :value="account.id">{{ account.system_no }} — {{ account.account_name }}</option></select></Field><Field label="Bank"><select v-model="form.bank_profile_id" class="form-select"><option :value="null">Select Bank</option><option v-for="bank in options.banks" :key="bank.id" :value="bank.id">{{ bank.bank_name }} — {{ bank.account_name }}</option></select></Field><Field label="Currency" required><select v-model="form.currency_id" class="form-select" required><option :value="null">Select Currency</option><option v-for="currency in options.currencies" :key="currency.id" :value="currency.id">{{ currency.currency_code }} — {{ currency.currency_name }}</option></select></Field><Field label="Annual Fee"><input v-model.number="form.annual_fee" type="number" min="0" step=".01" class="form-control" /></Field><Field label="Payment Due Day"><DaySelect v-model="form.payment_due_day" nullable /></Field><Field label="Grace Period (Days)"><input v-model.number="form.grace_period_days" type="number" min="0" class="form-control" /></Field><Field label="Minimum Payment (%)"><input v-model.number="form.minimum_payment_percent" type="number" min="0" max="100" step=".01" class="form-control" /></Field><Field label="Interest Rate (%)"><input v-model.number="form.interest_rate" type="number" min="0" max="100" step=".01" class="form-control" /></Field></div></section>
        <section class="card cc-section"><h2>▣ Additional Information</h2><div class="cc-grid four"><Field label="Card Category" required><select v-model="form.card_category" class="form-select"><option>Corporate</option><option>Business</option><option>Personal</option></select></Field><Field label="Department"><input v-model="form.department" class="form-control" placeholder="Select or enter department" /></Field><Field label="Assigned To"><select v-model="form.assigned_to" class="form-select"><option :value="null">Select User</option><option v-for="user in options.users" :key="user.id" :value="user.id">{{ user.name || user.email }}</option></select></Field><Field label="Notes"><textarea v-model="form.notes" class="form-control" rows="1" /></Field></div></section>
        <div class="cc-actions"><label><input v-model="form.is_default" type="checkbox" /> Set as default card</label><div><button type="button" class="btn btn-light border me-2" @click="resetForm">Cancel</button><button class="btn btn-primary" :disabled="saving">▣ {{ saving ? 'Saving…' : (form.id ? 'Update Credit Card' : 'Save Credit Card') }}</button><button v-if="form.id" type="button" class="btn btn-outline-danger ms-2" @click="remove(form)">Delete</button></div></div>
      </form>
    </div>
  </main></AccountLayout>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, ref } from 'vue'
import client from '../api/client'
import AccountLayout from '../components/AccountLayout.vue'
const Field=defineComponent({props:{label:String,required:Boolean},setup(p,{slots}){return()=>h('label',{class:'cc-field'},[h('span',p.label+(p.required?' *':'')),slots.default?.()])}})
const ordinal=(day)=>`${day}${[1,21,31].includes(day)?'st':[2,22].includes(day)?'nd':[3,23].includes(day)?'rd':'th'} of every month`
const DaySelect=defineComponent({props:{modelValue:[Number,String],nullable:Boolean},emits:['update:modelValue'],setup(p,{emit}){return()=>h('select',{class:'form-select',value:p.modelValue??'',onChange:e=>emit('update:modelValue',e.target.value?Number(e.target.value):null)},[(p.nullable?h('option',{value:''},'Select day'):null),...Array.from({length:31},(_,i)=>h('option',{value:i+1},ordinal(i+1)))].filter(Boolean))}})
const cards=ref([]), options=ref({currencies:[],banks:[],accounts:[],countries:[],users:[]}), search=ref(''), saving=ref(false), error=ref('')
const cardTypes=['Visa','Mastercard','American Express','Discover','Other'],networks=['VISA','MASTER CARD','AMERICAN EXPRESS','DISCOVER','OTHER']
const blank=()=>({card_nickname:'',card_number:'',cvv:'',cardholder_name:'',card_type:'Visa',card_network:'VISA',expiry_date:'',credit_limit:0,current_balance:0,billing_day:1,due_day:20,pay_day:25,status_active:true,card_category:'Corporate',currency_id:null,bank_profile_id:null,account_holder_id:null,annual_fee:0,payment_due_day:null,grace_period_days:null,minimum_payment_percent:null,interest_rate:null,billing_address:'',city:'',state:'',postal_code:'',country_id:null,phone_number:'',email:'',department:'',assigned_to:null,notes:'',is_default:false})
const form=ref(blank()); const filteredCards=computed(()=>cards.value.filter(c=>`${c.card_nickname} ${c.card_no} ${c.card_last_four}`.toLowerCase().includes(search.value.toLowerCase())));const totalLimit=computed(()=>cards.value.reduce((sum,c)=>sum+Number(c.credit_limit),0));const totalBalance=computed(()=>cards.value.reduce((sum,c)=>sum+Number(c.current_balance),0));const activeCards=computed(()=>cards.value.filter(c=>c.status_active).length);const availableCredit=computed(()=>Math.max(0,Number(form.value.credit_limit||0)-Number(form.value.current_balance||0)))
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n||0));const brandLabel=c=>c.card_type==='American Express'?'AMEX':c.card_type==='Mastercard'?'MC':c.card_type.toUpperCase();const load=async()=>{const [list,opts]=await Promise.all([client.get('/credit-cards'),client.get('/credit-cards/options')]);cards.value=list.data.data;options.value=opts.data.data};const newCard=()=>{form.value=blank();error.value=''};const resetForm=newCard;const edit=card=>{form.value={...blank(),...card,card_number:''};error.value=''};const save=async()=>{saving.value=true;error.value='';try{const payload={...form.value};const r=form.value.id?await client.put(`/credit-cards/${form.value.id}`,payload):await client.post('/credit-cards',payload);await load();edit(r.data.data)}catch(e){error.value=e.response?.data?.message||'Unable to save credit card.'}finally{saving.value=false}};const remove=async card=>{if(!confirm(`Delete ${card.card_nickname}?`))return;await client.delete(`/credit-cards/${card.id}`);await load();newCard()};onMounted(()=>load().catch(()=>error.value='Unable to load credit cards.'))
</script>

<style scoped>
.cc-page{padding:28px;background:linear-gradient(120deg,#f8faff,#eef3ff);min-height:100vh;color:#071750}.cc-header{display:flex;justify-content:space-between;align-items:center;margin:0 auto 22px;max-width:1450px}.cc-header h1{font-size:2.2rem;font-weight:800;margin:0}.cc-header p{margin:4px 0 0;font-size:1.05rem}.cc-kicker{font-size:.72rem!important;font-weight:800;color:#2160ed!important;letter-spacing:.08em}.cc-stats{max-width:1450px;margin:0 auto 20px;display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.cc-stats article{background:#fff;border:1px solid #dce5fa;border-radius:12px;padding:14px;display:grid;grid-template-columns:42px 1fr;box-shadow:0 4px 12px #2040800d}.cc-stats span{grid-row:span 2;width:36px;height:36px;display:grid;place-items:center;background:#eaf0ff;color:#0757ef;border-radius:10px;font-weight:bold}.cc-stats small{color:#617096}.cc-stats b{font-size:1.2rem}.cc-layout{max-width:1450px;margin:auto;display:grid;grid-template-columns:310px 1fr;gap:18px}.card{background:#fff;border:1px solid #dce5fa;border-radius:13px;box-shadow:0 4px 16px #173a780d}.cc-list{height:max-content;overflow:hidden}.cc-list-head{padding:16px;display:flex;align-items:center;justify-content:space-between;gap:8px}.cc-list h2,.cc-section h2{font-size:1rem;font-weight:800;margin:0}.cc-search{padding:0 16px 12px}.cc-card{display:flex;width:100%;gap:10px;align-items:center;border:0;border-top:1px solid #edf0f8;background:#fff;padding:13px;text-align:left}.cc-card:hover,.cc-card.selected{background:#f1f5ff;outline:1px solid #1c60ff;outline-offset:-1px}.cc-brand{width:42px;height:42px;border-radius:7px;display:grid;place-items:center;background:#0757e9;color:#fff;font-size:.72rem;font-weight:900}.cc-brand.mastercard{background:#171717}.cc-brand.american-express{background:#0569dc}.cc-card-data{flex:1;min-width:0;display:grid;gap:3px}.cc-card-data b{font-size:.8rem}.cc-card-data small,.cc-card-data em{font-size:.7rem;color:#405078;font-style:normal}.cc-card .badge{font-size:.65rem}.cc-form{display:grid;gap:12px}.cc-section{padding:16px}.cc-section h2{margin-bottom:14px}.cc-grid{display:grid;gap:12px}.cc-grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.cc-grid.five{grid-template-columns:repeat(5,minmax(0,1fr));margin-top:14px;padding-top:14px;border-top:1px solid #edf0f8}.cc-field{display:grid;gap:5px;font-size:.73rem;font-weight:800}.cc-field>span{color:#071750}.cc-field>span::first-letter{}.cc-field :deep(.form-control),.cc-field :deep(.form-select){font-size:.82rem;min-height:38px}.cc-readonly{min-height:38px;border:1px solid #dce5fa;background:#f8faff;border-radius:.375rem;padding:9px;font-size:.85rem;color:#10702f}.cc-actions{background:#fff;border:1px solid #dce5fa;padding:16px;border-radius:13px;display:flex;justify-content:space-between;align-items:center;font-size:.85rem;font-weight:700}.cc-actions label{display:flex;align-items:center;gap:8px}.cc-actions input{width:18px;height:18px}@media(max-width:1100px){.cc-layout{grid-template-columns:1fr}.cc-list{max-height:340px;overflow:auto}.cc-grid.four{grid-template-columns:repeat(2,1fr)}.cc-grid.five{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.cc-page{padding:16px}.cc-header,.cc-actions{align-items:flex-start;gap:12px;flex-direction:column}.cc-header h1{font-size:1.65rem}.cc-stats{grid-template-columns:repeat(2,1fr)}.cc-grid.four,.cc-grid.five{grid-template-columns:1fr}.cc-actions div{display:flex;flex-wrap:wrap;gap:6px}.cc-actions .me-2,.cc-actions .ms-2{margin:0!important}}
</style>
